package nvfm

// ExtendedInterface defines extensions to the core Fabric Manager API.
type ExtendedInterface interface {
	LookupSymbol(string) error
}

type libraryOptions struct {
	path  string
	flags int
}

// LibraryOption configures the underlying Fabric Manager library.
type LibraryOption func(*libraryOptions)

// WithLibraryPath sets the shared library name or path used for libnvfm.
func WithLibraryPath(path string) LibraryOption {
	return func(o *libraryOptions) {
		o.path = path
	}
}

// SetLibraryOptions applies options to the package-level Fabric Manager library.
// If the library is already initialized, an error is returned.
func SetLibraryOptions(opts ...LibraryOption) error {
	libnvfm.Lock()
	defer libnvfm.Unlock()
	if libnvfm.refcount != 0 {
		return errLibraryAlreadyLoaded
	}
	libnvfm.init(opts...)
	return nil
}

